def main():
 audit={r['sheet']:r for b in json.loads((ROOT/'evidence/sheet_report_number_audit.json').read_text())['workbooks'] if b['file']==SRC for r in b['rows']};dates={r['sheet']:r for b in json.loads((ROOT/'evidence/status_report_date_audit.json').read_text())['workbooks'] if b['file']==SRC for r in b['rows']};wb=load_workbook(ROOT/SRC,read_only=True,data_only=True);items=[]
 for prefix,cells,anchor,en,fa in EVENTS:
  sheet=f'{prefix}-1 DDR Remark';values={c:wb[sheet][c].value for c in cells};assert all(isinstance(v,str) and v.strip() for v in values.values()),(sheet,values);assert anchor.lower() in ' '.join(values.values()).lower(),(sheet,anchor);num=audit[sheet]['header_report_number'];assert num==prefix
  items.append({'sheet':sheet,'worksheet_prefix':prefix,'header_report_number':num,'header_date_unverified':dates[sheet]['report_date_iso_from_header'],'cells':values,'anchor':anchor,'english':en,'persian':fa})
 wb.close();items.sort(key=lambda x:x['header_report_number']);pg=' '.join(PdfReader(ROOT/PROGRAM).pages[6].extract_text().split());assert '44.2 days (Main Plan) + 95 Days (Contingency Plan)' in pg
 c=load_workbook(ROOT/CBS,read_only=True,data_only=True);f=load_workbook(ROOT/CBS,read_only=True,data_only=False);name='Total Cost-EPD & Rigless';refs=['B3','C3','B4','C4','A5','C5'];financial={x:{'cached':c[name][x].value,'formula_or_literal':f[name][x].value} for x in refs};c.close();f.close()
 data={'well':'166','source':SRC,'method':'One selected observation per recognized status page, ordered by source header, not verified chronology or a complete hourly reconstruction.','events':items,'programme':{'file':PROGRAM,'physical_page':7,'text_excerpt':pg},'cbs':{'file':CBS,'sheet':name,'cells':financial,'caveat':'Source-labelled ceiling, cached not recalculated, not actual expenditure or authorization.'},'limitations':'One selected observation per page does not establish every event or hour, signed acceptance, current barriers, expenditure or liability.'};(ROOT/'evidence/166_campaign_review.json').write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n')
 for lang in ('EN','FA'):
  fa=lang=='FA';path=ROOT/f'166_Drilling_Engineering_Report_{lang}.docx';d=Document(path);title='بازسازی منتخب عملیات تعمیر چاه ۱۶۶' if fa else 'Selected AZNS-166 workover campaign reconstruction'
  if any(p.text==title for p in d.paragraphs):continue
  anchor=next(p for p in d.paragraphs if p.text in ('Performance and Parameter Analysis','تحلیل عملکرد و پارامترهای عملیاتی'));h=d.add_heading(title,level=2);h.alignment=1;anchor._p.addprevious(h._p)
  p=d.add_paragraph('از هر یک از ۲۴ صفحه شناسایی‌شده یک مدخل منتخب به ترتیب شماره سرصفحه ارائه شده است؛ این پوشش منتخب معادل بازسازی همه ساعت‌ها یا تأیید ترتیب و تاریخ نیست. تأیید با سوابق امضاشده ضروری است.' if fa else 'One selected entry from each of the 24 recognized pages is presented in source-header order; this selective coverage is not a reconstruction of every hour or validation of order and dates. Signed-record reconciliation is essential.');style(p,fa);anchor._p.addprevious(p._p)
